local Util = ReplicatedStorage:WaitForChild("Util")
local Common = ReplicatedStorage:WaitForChild("Common")
local Remotes = ReplicatedStorage:WaitForChild("Remotes")
local Assets = ReplicatedStorage:WaitForChild("Assets")
local FX = ReplicatedStorage:WaitForChild("FX")

local function setupV(v)
	v:GetAttribute("Id")
	v:GetAttribute("Id")
end

task.spawn(function()
	for _, util in ipairs({
		Util, Common, Remotes, Assets, FX,
	}) do
		local children17 = util:GetChildren()

		for i10, v37 in ipairs(children17) do
			setupV(v37)
		end

		util.ChildAdded:Connect(function(child)
			child:GetAttribute("Id")
			child:GetAttribute("Id")
		end)
	end
end)

task.spawn(function()
	local Modules = ReplicatedStorage:WaitForChild("Modules")
	local Net = Modules:WaitForChild("Net")
	require(Net)
	ReplicatedStorage.Modules.Net:WaitForChild("seed")
	ReplicatedStorage.Modules.Net:WaitForChild("RE/RegisterAttack")
	ReplicatedStorage.Modules.Net:WaitForChild("RE/RegisterHit")
	task.wait(1)
	task.wait(1)
	-- [envlog] the statements above repeat forever (loop)
end)

