Section8:AddButton({
	Title = "Teleport to the top of the big tree",
	Description = "",
	Callback = function(state)
		game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")

		if state then
			local tween9 = TweenService:Create(game.Players.LocalPlayer.Character.HumanoidRootPart, TweenInfo.new(0, Enum.EasingStyle.Linear), { CFrame = CFrame.new(3026.89453125, 2281.0227050781, -7328.9663085938) })
			local descendants11 = game.Players.LocalPlayer.Character:GetDescendants()

			for k35, v51 in pairs(descendants11) do
				v51.CanCollide = false
			end

			tween9:Play()

			tween9.Completed:Connect(function(playbackState)
				game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
				game.Players.LocalPlayer.Character.HumanoidRootPart.CanCollide = true
			end)
		else
			local tween10 = TweenService:Create(game.Players.LocalPlayer.Character.HumanoidRootPart, TweenInfo.new(0, Enum.EasingStyle.Linear), { CFrame = CFrame.new(3026.89453125, 2281.0227050781, -7328.9663085938) })
			local descendants12 = game.Players.LocalPlayer.Character:GetDescendants()

			for k36, v52 in pairs(descendants12) do
				v52.CanCollide = false
			end

			tween10:Play()

			tween10.Completed:Connect(function(playbackState2)
				game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
				game.Players.LocalPlayer.Character.HumanoidRootPart.CanCollide = true
			end)
		end
	end
})

