Section8:AddButton({
	Title = "Teleport to Temple of Time",
	Description = "",
	Callback = function(state)
		if state then
			task.spawn(function()
				local MapStash = ReplicatedStorage:WaitForChild("MapStash", 5)
				MapStash:FindFirstChild("Temple of Time")
				workspace:FindFirstChild("Temple of Time")
				local Remotes4 = ReplicatedStorage:WaitForChild("Remotes")
				local CommF_ = Remotes4:WaitForChild("CommF_")
				local HumanoidRootPart5 = Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
				CommF_:InvokeServer("RaceV4Progress", "Check")
				task.wait(0.5)
				CommF_:InvokeServer("RaceV4Progress", "Teleport")
				task.wait(1)
				HumanoidRootPart5.Velocity = Vector3.new(0, 0, 0)
				HumanoidRootPart5.CFrame = CFrame.new(Vector3.new(28286, 14897, 103))
				HumanoidRootPart5.Anchored = true
				task.wait(1)
				HumanoidRootPart5.Anchored = false
				task.wait(0.2)
			end)
		else
			task.spawn(function()
				local MapStash2 = ReplicatedStorage:WaitForChild("MapStash", 5)
				MapStash2:FindFirstChild("Temple of Time")
				workspace:FindFirstChild("Temple of Time")
				local Remotes5 = ReplicatedStorage:WaitForChild("Remotes")
				local CommF_2 = Remotes5:WaitForChild("CommF_")
				local HumanoidRootPart6 = Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
				CommF_2:InvokeServer("RaceV4Progress", "Check")
				task.wait(0.5)
				CommF_2:InvokeServer("RaceV4Progress", "Teleport")
				task.wait(1)
				HumanoidRootPart6.Velocity = Vector3.new(0, 0, 0)
				HumanoidRootPart6.CFrame = CFrame.new(Vector3.new(28286, 14897, 103))
				HumanoidRootPart6.Anchored = true
				task.wait(1)
				HumanoidRootPart6.Anchored = false
				task.wait(0.2)
			end)
		end
	end
})

task.spawn(function()
