Section7:AddSeperator("Only in Sea 3")

local Toggle6 = Section6:AddToggle({
	Title = "Auto Remove Cooldown Leviathan",
	Description = "Automatically farms Sea Events to remove the Leviathan cooldown",
	Default = false,
	Callback = function(state)
		if state then
			_G.AutoRemoveLeviathan = state

			task.spawn(function(...)
				ReplicatedStorage.Remotes.CommF_:InvokeServer("InfoLeviathan", "1")
				_G.AutoRemoveLeviathan = false

				task.defer(function()
					Toggle6:SetValue(false)
				end)

				Window:Notify({
		Text = "Leviathan cooldown has been removed!",
		Title = "Night Mystic",
		Duration = 7,
		Icon = "rbxassetid://73539136006332",
		IconColor = Color3.new(1, 1, 1)
	})

				task.wait(5)
			end)
		end
	end
})

_G.DriveBoatOwner = "None"
