Section15:AddSeperator("Dealer")

Section15:AddButton({
	Title = "Open Fruit Dealer",
	Description = "Opens normal fruit shop",
	Callback = function(state)
		if state then
			local Main2 = game.Players.LocalPlayer.PlayerGui:WaitForChild("Main")
			local UIController = Main2:WaitForChild("UIController")
			local FruitShop = UIController:WaitForChild("FruitShop")
			local module2 = require(FruitShop)
			module2:Open("FruitDealer")
		else
			local Main3 = game.Players.LocalPlayer.PlayerGui:WaitForChild("Main")
			local UIController2 = Main3:WaitForChild("UIController")
			local FruitShop2 = UIController2:WaitForChild("FruitShop")
			local module3 = require(FruitShop2)
			module3:Open("FruitDealer")
		end
	end
})

Section15:AddButton({
	Title = "Open Advanced Fruit Dealer",
	Description = "Opens advanced fruit shop",
	Callback = function(state)
		if state then
			local Main4 = game.Players.LocalPlayer.PlayerGui:WaitForChild("Main")
			local UIController3 = Main4:WaitForChild("UIController")
			local FruitShop3 = UIController3:WaitForChild("FruitShop")
